import fs from "node:fs";
import path from "node:path";
import { loadRoleAssets } from "./assets.js";
import { FeatureSession } from "./pcm.js";
import { WenetEngine } from "./wenet.js";
import { MunetEngine } from "./munet.js";
import {
  blendWeight,
  cropRgb,
  decodeFrame,
  encodeJpeg,
  hwcToChw,
  normalizeRgb,
  pasteRgb,
  prep160,
  resizeRgb,
  rgbaToRgb,
  toPcm16k,
  unsharpRgb,
} from "./image.js";

/**
 * Node DUIX session.
 *
 * baseDir  — gj_dh_res (wenet.o + weight_168u.b)
 * roleDir  — role package (frames, bbox, config, wasm/)
 */
export class Duix {
  constructor({ baseDir, roleDir, cacheDir } = {}) {
    if (!baseDir || !roleDir) throw new Error("baseDir and roleDir are required");
    this.baseDir = baseDir;
    this.roleDir = roleDir;
    this.cacheDir = cacheDir;
    this.assets = null;
    this.wenet = null;
    this.munet = null;
    this.features = null;
    this._frameCache = new Map();
    this._lipPrep = new Map();
  }

  async init() {
    this.assets = await loadRoleAssets({
      baseDir: this.baseDir,
      roleDir: this.roleDir,
      cacheDir: this.cacheDir,
    });
    this.wenet = new WenetEngine(this.assets.wenetPath);
    await this.wenet.init();
    this.munet = new MunetEngine();
    await this.munet.init(this.assets.paramPath, this.assets.binPath, this.assets.blobs);
    this.features = null;
    return {
      width: this.assets.width,
      height: this.assets.height,
      frames: this.assets.frames.length,
      wenet: this.assets.wenetPath,
      param: this.assets.paramPath,
      bin: this.assets.binPath,
    };
  }

  /** Push a whole 16 kHz mono s16le PCM buffer and compute BNF windows. */
  async pushPcm(pcm) {
    const src = Buffer.isBuffer(pcm) ? pcm : Buffer.from(pcm);
    this.playbackPcm = src;
    this.features = new FeatureSession(this.wenet);
    return this.features.ingest(src);
  }

  async pushWav(wavPath) {
    const pcm = toPcm16k(fs.readFileSync(wavPath));
    return this.pushPcm(pcm);
  }

  _loadRgb(filePath) {
    const hit = this._frameCache.get(filePath);
    if (hit) return hit;
    const decoded = decodeFrame(filePath);
    const rgb = rgbaToRgb(decoded.rgba, decoded.width, decoded.height);
    const image = { width: decoded.width, height: decoded.height, rgb };
    if (this._frameCache.size > 32) {
      const first = this._frameCache.keys().next().value;
      this._frameCache.delete(first);
    }
    this._frameCache.set(filePath, image);
    return image;
  }

  /**
   * Face crop and 6-channel tensor for one silence frame.
   * Independent of audio, so realtime frames reuse it.
   */
  _prepLip(frameIndex) {
    const n = this.assets.frames.length;
    const slot = ((frameIndex % n) + n) % n;
    const hit = this._lipPrep.get(slot);
    if (hit) return hit;
    const image = this._loadRgb(this.assets.frames[slot]);
    const width = image.width || this.assets.width;
    const height = image.height || this.assets.height;
    const box = this.assets.boxes[slot] || this.assets.boxes[0];
    if (!box || box.length < 4) return null;
    let [x1, y1, x2, y2] = box.map((v) => v | 0);
    x1 = Math.max(0, Math.min(width - 1, x1));
    y1 = Math.max(0, Math.min(height - 1, y1));
    x2 = Math.max(x1 + 1, Math.min(width, x2));
    y2 = Math.max(y1 + 1, Math.min(height, y2));
    const bw = x2 - x1;
    const bh = y2 - y1;
    const roi = cropRgb(image.rgb, width, x1, y1, bw, bh);
    const rgb168 = resizeRgb(roi, bw, bh, 168, 168);
    const { real, mask } = prep160(rgb168);
    const face = new Float32Array(6 * 160 * 160);
    face.set(hwcToChw(normalizeRgb(real), 160, 160, 3), 0);
    face.set(hwcToChw(normalizeRgb(mask), 160, 160, 3), 3 * 160 * 160);
    const prep = { width, height, x1, y1, bw, bh, rgb168, real, face };
    this._lipPrep.set(slot, prep);
    return prep;
  }

  /**
   * Realtime mouth patch for the audio window at `audioIndex`,
   * pasted back to the face box of silence frame `frameIndex`.
   */
  async renderMouth(frameIndex, audioIndex) {
    if (!this.assets) throw new Error("call init() first");
    if (!this.features) throw new Error("push audio before renderMouth");
    const prep = this._prepLip(frameIndex);
    const feat = this.features.readWindow(audioIndex);
    if (!prep || !feat) return null;
    const t0 = performance.now();
    const mouth = await this.munet.infer(prep.face, feat);
    const inferMs = performance.now() - t0;
    const sharp = unsharpRgb(mouth, 160, 160);
    const blended = blendWeight(sharp, prep.real, this.assets.mask);
    const back168 = prep.rgb168.slice();
    pasteRgb(back168, 168, blended, 4, 4, 160, 160);
    const restored = resizeRgb(back168, 168, 168, prep.bw, prep.bh);
    return {
      x: prep.x1,
      y: prep.y1,
      w: prep.bw,
      h: prep.bh,
      width: prep.width,
      height: prep.height,
      rgb: restored,
      inferMs,
    };
  }

  /**
   * Render one frame.
   * frameIndex selects the silence picture (loops).
   * audioIndex selects the 40ms BNF window. Omit it to return the raw frame.
   */
  async render(frameIndex, audioIndex = null) {
    if (!this.assets) throw new Error("call init() first");
    const n = this.assets.frames.length;
    const framePath = this.assets.frames[((frameIndex % n) + n) % n];
    const image = this._loadRgb(framePath);
    const rgb = image.rgb.slice();
    const width = image.width || this.assets.width;
    const height = image.height || this.assets.height;
    if (audioIndex == null || !this.features) {
      return { width, height, rgb, lip: false };
    }
    const mouth = await this.renderMouth(frameIndex, audioIndex);
    if (!mouth) return { width, height, rgb, lip: false };
    pasteRgb(rgb, width, mouth.rgb, mouth.x, mouth.y, mouth.w, mouth.h);
    return { width, height, rgb, lip: true };
  }

  /** JPEG bytes for one frame. `audioIndex` null returns the silence picture. */
  async renderJpeg(frameIndex, audioIndex = null, quality = 85) {
    const frame = await this.render(frameIndex, audioIndex);
    return encodeJpeg(frame.rgb, frame.width, frame.height, quality);
  }

  /**
   * Drive a WAV file and write one JPEG per 40ms frame.
   * Returns the number of frames written.
   */
  async driveWav(wavPath, { outDir, onFrame } = {}) {
    const blocks = await this.pushWav(wavPath);
    if (outDir) fs.mkdirSync(outDir, { recursive: true });
    for (let i = 0; i < blocks; i++) {
      const frame = await this.render(i, i);
      const jpeg = encodeJpeg(frame.rgb, frame.width, frame.height);
      if (outDir) {
        const name = String(i).padStart(5, "0") + ".jpg";
        fs.writeFileSync(path.join(outDir, name), jpeg);
      }
      if (onFrame) await onFrame({ index: i, total: blocks, ...frame, jpeg });
    }
    return blocks;
  }

  close() {
    if (this.munet) this.munet.close();
    this.munet = null;
    this.wenet = null;
  }
}
